package com.yuegang.zhihui.ai.application;import com.yuegang.zhihui.ai.api.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;
public final class AiEvaluationService{private final JdbcTemplate jdbc;private final ChatService chat;private final EvidenceCoverageEvaluator evaluator=new EvidenceCoverageEvaluator();public AiEvaluationService(DataSource d,ChatService c){jdbc=new JdbcTemplate(d);chat=c;}public AiAdminSummaryView summary(){return jdbc.query("SELECT (SELECT COUNT(*) FROM ai_conversation),(SELECT COUNT(*) FROM ai_message),(SELECT COUNT(*) FROM ai_message WHERE refused=TRUE),(SELECT COUNT(*) FROM ai_feedback),(SELECT COUNT(*) FROM ai_feedback WHERE helpful=TRUE),(SELECT COUNT(*) FROM ai_evaluation_case WHERE enabled=TRUE),(SELECT COUNT(*) FROM ai_prompt_config WHERE enabled=TRUE)",r->{r.next();return new AiAdminSummaryView(r.getLong(1),r.getLong(2),r.getLong(3),r.getLong(4),r.getLong(5),r.getLong(6),r.getLong(7)>0);});}public List<EvaluationRunView>run(long operator){var cases=jdbc.query("SELECT id,category,question,expected_evidence,forbidden_answer,expected_refusal FROM ai_evaluation_case WHERE enabled=TRUE ORDER BY category,id",(r,n)->new Case(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getBoolean(6)));var out=new ArrayList<EvaluationRunView>();for(var c:cases){long start=System.nanoTime(),id=next();boolean passed=false;double score=0;int citations=0;String reason=null,answer=null;try{var result=chat.chat(operator,new ChatRequest(null,c.question,c.category,false));answer=result.answer();citations=result.citations().size();var evaluation=evaluator.evaluate(result,c.expectedEvidence,c.forbidden,c.expectedRefusal);passed=evaluation.passed();score=evaluation.score();reason=evaluation.reason();}catch(RuntimeException e){reason="EVALUATION_EXECUTION_FAILED";}long duration=(System.nanoTime()-start)/1_000_000;jdbc.update("INSERT INTO ai_evaluation_run(id,case_id,answer,citation_count,passed,score,failure_reason,duration_ms) VALUES(?,?,?,?,?,?,?,?)",id,c.id,answer,citations,passed,score,reason,duration);out.add(new EvaluationRunView(Long.toString(id),Long.toString(c.id),passed,score,citations,duration,reason));}return out;}private record Case(long id,String category,String question,String expectedEvidence,String forbidden,boolean expectedRefusal){}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
